public class BankAccountTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount();
        check("new account balance", 0.0, account.getBalance());
        check("deposit(50.0)", true, account.deposit(50.0));
        check("balance after deposit", 50.0, account.getBalance());
        check("withdraw(20.0)", true, account.withdraw(20.0));
        check("balance after withdraw", 30.0, account.getBalance());
        check("withdraw(100.0) overdraft", false, account.withdraw(100.0));
        check("deposit(-5.0) rejected", false, account.deposit(-5.0));
        check("withdraw(0.0) rejected", false, account.withdraw(0.0));
        check("balance unchanged after rejects", 30.0, account.getBalance());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

